let timer = null;
let isRunning = false;
let secondsLeft = 25 * 60; // 25 minutes in seconds
let isBreakTime = false;

const timerDisplay = document.getElementById('timer');
const startBtn = document.getElementById('startBtn');
const stopBtn = document.getElementById('stopBtn');
const resetBtn = document.getElementById('resetBtn');
const countDisplay = document.getElementById('count');
const notification = document.getElementById('notification');

function updateTimerDisplay() {
    const minutes = Math.floor(secondsLeft / 60);
    const seconds = secondsLeft % 60;
    timerDisplay.textContent = `${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
}

function startTimer() {
    if (isRunning) return;

    isRunning = true;
    timer = setInterval(() => {
        secondsLeft--;
        updateTimerDisplay();

        if (secondsLeft <= 0) {
            clearInterval(timer);
            isRunning = false;

            if (!isBreakTime) {
                // Pomodoro time finished, start break
                isBreakTime = true;
                secondsLeft = 5 * 60; // 5 minutes break
                showNotification('休息時間到！');
                updateTimerDisplay();
                startTimer(); // Auto-start break timer
            } else {
                // Break time finished, increment count and start new pomodoro
                isBreakTime = false;
                secondsLeft = 25 * 60; // 25 minutes
                incrementCount();
                showNotification('新的番茄鐘開始！');
                updateTimerDisplay();
            }
        }
    }, 1000);
}

function stopTimer() {
    if (!isRunning) return;

    clearInterval(timer);
    isRunning = false;
}

function resetTimer() {
    stopTimer();
    secondsLeft = isBreakTime ? 5 * 60 : 25 * 60; // Reset to current mode
    updateTimerDisplay();
}

function incrementCount() {
    fetch('api/count/increment', { method: 'POST' })
        .then(response => response.json())
        .then(data => {
            countDisplay.textContent = data.count;
        });
}

function getCount() {
    fetch('api/count')
        .then(response => response.json())
        .then(data => {
            countDisplay.textContent = data.count;
        });
}

function showNotification(message) {
    notification.textContent = message;
    notification.style.display = 'block';

    setTimeout(() => {
        notification.style.display = 'none';
    }, 3000);
}

// Initialize the display
getCount();
updateTimerDisplay();

startBtn.addEventListener('click', startTimer);
stopBtn.addEventListener('click', stopTimer);
resetBtn.addEventListener('click', resetTimer);

